INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:numbers_0_10_examples', '{"reply":"Aquí tienes frases de ejemplo con los números del 0 al 10:\n\nEnglish: Zero. My phone balance is zero.\nEspañol: El saldo de mi teléfono está a cero.\n\nEnglish: One. I have one brother.\nEspañol: Tengo un hermano.\n\nEnglish: Two. She has two cats.\nEspañol: Ella tiene dos gatos.\n\nEnglish: Three. There are three books on the table.\nEspañol: Hay tres libros sobre la mesa.\n\nEnglish: Four. My car has four doors.\nEspañol: Mi coche tiene cuatro puertas.\n\nEnglish: Five. I have five fingers on each hand.\nEspañol: Tengo cinco dedos en cada mano.\n\nEnglish: Six. He bought six apples.\nEspañol: Él compró seis manzanas.\n\nEnglish: Seven. I get up at seven o''clock.\nEspañol: Me levanto a las siete.\n\nEnglish: Eight. There are eight students in our class.\nEspañol: Hay ocho estudiantes en nuestra clase.\n\nEnglish: Nine. We need nine chairs.\nEspañol: Necesitamos nueve sillas.\n\nEnglish: Ten. They have ten pounds.\nEspañol: Tienen diez libras.","spokenSpanish":"Aquí tienes frases de ejemplo con los números del 0 al 10:","pronunciationText":"Zero. My phone balance is zero.\nOne. I have one brother.\nTwo. She has two cats.\nThree. There are three books on the table.\nFour. My car has four doors.\nFive. I have five fingers on each hand.\nSix. He bought six apples.\nSeven. I get up at seven o''clock.\nEight. There are eight students in our class.\nNine. We need nine chairs.\nTen. They have ten pounds.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:greetings_examples', '{"reply":"Aquí tienes frases para saludar en inglés:\n\nEnglish: Hello! How are you?\nEspañol: ¡Hola! ¿Cómo estás?\n\nEnglish: Good morning. Did you sleep well?\nEspañol: Buenos días. ¿Has dormido bien?\n\nEnglish: Nice to meet you.\nEspañol: Encantado de conocerte.\n\nEnglish: How have you been?\nEspañol: ¿Qué tal te ha ido?\n\nEnglish: See you later!\nEspañol: ¡Hasta luego!","spokenSpanish":"Aquí tienes frases para saludar en inglés:","pronunciationText":"Hello! How are you?\nGood morning. Did you sleep well?\nNice to meet you.\nHow have you been?\nSee you later!","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:self_introduction_examples', '{"reply":"Aquí tienes frases para presentarte en inglés:\n\nEnglish: My name is Alex.\nEspañol: Me llamo Alex.\n\nEnglish: I am from Spain.\nEspañol: Soy de España.\n\nEnglish: I live in Barcelona.\nEspañol: Vivo en Barcelona.\n\nEnglish: I work in an office.\nEspañol: Trabajo en una oficina.\n\nEnglish: In my free time, I enjoy reading.\nEspañol: En mi tiempo libre, disfruto leyendo.","spokenSpanish":"Aquí tienes frases para presentarte en inglés:","pronunciationText":"My name is Alex.\nI am from Spain.\nI live in Barcelona.\nI work in an office.\nIn my free time, I enjoy reading.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:days_of_week_examples', '{"reply":"Aquí tienes frases con los días de la semana:\n\nEnglish: I work on Monday.\nEspañol: Trabajo el lunes.\n\nEnglish: We have English lessons on Tuesday.\nEspañol: Tenemos clases de inglés el martes.\n\nEnglish: She visits her family on Friday.\nEspañol: Ella visita a su familia el viernes.\n\nEnglish: I usually relax on Saturday.\nEspañol: Normalmente descanso el sábado.\n\nEnglish: Sunday is my favourite day.\nEspañol: El domingo es mi día favorito.","spokenSpanish":"Aquí tienes frases con los días de la semana:","pronunciationText":"I work on Monday.\nWe have English lessons on Tuesday.\nShe visits her family on Friday.\nI usually relax on Saturday.\nSunday is my favourite day.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:months_of_year_examples', '{"reply":"Aquí tienes frases con los meses del año:\n\nEnglish: My birthday is in April.\nEspañol: Mi cumpleaños es en abril.\n\nEnglish: We go on holiday in August.\nEspañol: Nos vamos de vacaciones en agosto.\n\nEnglish: School starts in September.\nEspañol: El colegio empieza en septiembre.\n\nEnglish: December is often cold.\nEspañol: Diciembre suele ser frío.","spokenSpanish":"Aquí tienes frases con los meses del año:","pronunciationText":"My birthday is in April.\nWe go on holiday in August.\nSchool starts in September.\nDecember is often cold.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:colours_examples', '{"reply":"Aquí tienes frases para practicar los colores:\n\nEnglish: The sky is blue.\nEspañol: El cielo es azul.\n\nEnglish: She has a red bag.\nEspañol: Ella tiene un bolso rojo.\n\nEnglish: The grass is green.\nEspañol: La hierba es verde.\n\nEnglish: My favourite colour is purple.\nEspañol: Mi color favorito es el morado.\n\nEnglish: The walls are white.\nEspañol: Las paredes son blancas.","spokenSpanish":"Aquí tienes frases para practicar los colores:","pronunciationText":"The sky is blue.\nShe has a red bag.\nThe grass is green.\nMy favourite colour is purple.\nThe walls are white.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:family_examples', '{"reply":"Aquí tienes frases sobre la familia:\n\nEnglish: I have two sisters.\nEspañol: Tengo dos hermanas.\n\nEnglish: My parents live nearby.\nEspañol: Mis padres viven cerca.\n\nEnglish: My cousin is very funny.\nEspañol: Mi primo es muy divertido.\n\nEnglish: We visit our grandparents on Sundays.\nEspañol: Visitamos a nuestros abuelos los domingos.","spokenSpanish":"Aquí tienes frases sobre la familia:","pronunciationText":"I have two sisters.\nMy parents live nearby.\nMy cousin is very funny.\nWe visit our grandparents on Sundays.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:food_examples', '{"reply":"Aquí tienes frases sobre comida y bebida:\n\nEnglish: I would like a glass of water, please.\nEspañol: Quisiera un vaso de agua, por favor.\n\nEnglish: She is making dinner.\nEspañol: Ella está preparando la cena.\n\nEnglish: I do not eat meat.\nEspañol: No como carne.\n\nEnglish: Could I see the menu, please?\nEspañol: ¿Podría ver la carta, por favor?\n\nEnglish: The soup is delicious.\nEspañol: La sopa está deliciosa.","spokenSpanish":"Aquí tienes frases sobre comida y bebida:","pronunciationText":"I would like a glass of water, please.\nShe is making dinner.\nI do not eat meat.\nCould I see the menu, please?\nThe soup is delicious.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:weather_examples', '{"reply":"Aquí tienes frases para hablar del tiempo:\n\nEnglish: It is sunny today.\nEspañol: Hoy hace sol.\n\nEnglish: It is going to rain later.\nEspañol: Va a llover más tarde.\n\nEnglish: It was very windy yesterday.\nEspañol: Ayer hizo mucho viento.\n\nEnglish: What is the weather like?\nEspañol: ¿Qué tiempo hace?","spokenSpanish":"Aquí tienes frases para hablar del tiempo:","pronunciationText":"It is sunny today.\nIt is going to rain later.\nIt was very windy yesterday.\nWhat is the weather like?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:restaurant_phrases', '{"reply":"Aquí tienes frases útiles para pedir en un restaurante:\n\nEnglish: Could I have the menu, please?\nEspañol: ¿Me trae la carta, por favor?\n\nEnglish: I would like the chicken, please.\nEspañol: Quisiera el pollo, por favor.\n\nEnglish: Could we have the bill, please?\nEspañol: ¿Nos trae la cuenta, por favor?\n\nEnglish: Does this dish contain nuts?\nEspañol: ¿Este plato contiene frutos secos?\n\nEnglish: Could I have a glass of water?\nEspañol: ¿Me trae un vaso de agua?","spokenSpanish":"Aquí tienes frases útiles para pedir en un restaurante:","pronunciationText":"Could I have the menu, please?\nI would like the chicken, please.\nCould we have the bill, please?\nDoes this dish contain nuts?\nCould I have a glass of water?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:hotel_phrases', '{"reply":"Aquí tienes frases útiles para un hotel:\n\nEnglish: I have a reservation under the name Smith.\nEspañol: Tengo una reserva a nombre de Smith.\n\nEnglish: What time is check-out?\nEspañol: ¿A qué hora hay que dejar la habitación?\n\nEnglish: Could I have an extra towel, please?\nEspañol: ¿Me podría dar una toalla extra, por favor?\n\nEnglish: The air conditioning is not working.\nEspañol: El aire acondicionado no funciona.","spokenSpanish":"Aquí tienes frases útiles para un hotel:","pronunciationText":"I have a reservation under the name Smith.\nWhat time is check-out?\nCould I have an extra towel, please?\nThe air conditioning is not working.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:airport_phrases', '{"reply":"Aquí tienes frases útiles para el aeropuerto:\n\nEnglish: Where is the check-in desk?\nEspañol: ¿Dónde está el mostrador de facturación?\n\nEnglish: Could you tell me which gate I need?\nEspañol: ¿Podría decirme qué puerta necesito?\n\nEnglish: I have only hand luggage.\nEspañol: Solo llevo equipaje de mano.\n\nEnglish: Has the flight been delayed?\nEspañol: ¿Se ha retrasado el vuelo?","spokenSpanish":"Aquí tienes frases útiles para el aeropuerto:","pronunciationText":"Where is the check-in desk?\nCould you tell me which gate I need?\nI have only hand luggage.\nHas the flight been delayed?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:directions_phrases', '{"reply":"Aquí tienes frases para pedir indicaciones:\n\nEnglish: Excuse me, how do I get to the station?\nEspañol: Disculpe, ¿cómo llego a la estación?\n\nEnglish: Turn left at the traffic lights.\nEspañol: Gire a la izquierda en el semáforo.\n\nEnglish: Go straight ahead for two blocks.\nEspañol: Siga recto durante dos manzanas.\n\nEnglish: Is it within walking distance?\nEspañol: ¿Está a una distancia que se pueda recorrer a pie?","spokenSpanish":"Aquí tienes frases para pedir indicaciones:","pronunciationText":"Excuse me, how do I get to the station?\nTurn left at the traffic lights.\nGo straight ahead for two blocks.\nIs it within walking distance?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:shopping_phrases', '{"reply":"Aquí tienes frases útiles para ir de compras:\n\nEnglish: How much does this cost?\nEspañol: ¿Cuánto cuesta esto?\n\nEnglish: Do you have this in a larger size?\nEspañol: ¿Tiene esto en una talla más grande?\n\nEnglish: Can I try it on?\nEspañol: ¿Me lo puedo probar?\n\nEnglish: Could I have the receipt, please?\nEspañol: ¿Me da el recibo, por favor?","spokenSpanish":"Aquí tienes frases útiles para ir de compras:","pronunciationText":"How much does this cost?\nDo you have this in a larger size?\nCan I try it on?\nCould I have the receipt, please?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:daily_routine_examples', '{"reply":"Aquí tienes frases sobre la rutina diaria:\n\nEnglish: I usually get up at seven.\nEspañol: Normalmente me levanto a las siete.\n\nEnglish: She has breakfast before work.\nEspañol: Ella desayuna antes de trabajar.\n\nEnglish: We take the bus to school.\nEspañol: Vamos al colegio en autobús.\n\nEnglish: He goes to bed at ten.\nEspañol: Él se acuesta a las diez.","spokenSpanish":"Aquí tienes frases sobre la rutina diaria:","pronunciationText":"I usually get up at seven.\nShe has breakfast before work.\nWe take the bus to school.\nHe goes to bed at ten.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:present_simple_examples', '{"reply":"Aquí tienes ejemplos del presente simple:\n\nEnglish: I work from Monday to Friday.\nEspañol: Trabajo de lunes a viernes.\n\nEnglish: She speaks English at work.\nEspañol: Ella habla inglés en el trabajo.\n\nEnglish: They do not drink coffee.\nEspañol: Ellos no beben café.\n\nEnglish: Does he live near here?\nEspañol: ¿Vive él cerca de aquí?","spokenSpanish":"Aquí tienes ejemplos del presente simple:","pronunciationText":"I work from Monday to Friday.\nShe speaks English at work.\nThey do not drink coffee.\nDoes he live near here?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:past_simple_examples', '{"reply":"Aquí tienes ejemplos del pasado simple:\n\nEnglish: I visited London last year.\nEspañol: Visité Londres el año pasado.\n\nEnglish: She bought a new coat yesterday.\nEspañol: Ella compró un abrigo nuevo ayer.\n\nEnglish: We did not see the film.\nEspañol: No vimos la película.\n\nEnglish: Did you enjoy the concert?\nEspañol: ¿Disfrutaste del concierto?","spokenSpanish":"Aquí tienes ejemplos del pasado simple:","pronunciationText":"I visited London last year.\nShe bought a new coat yesterday.\nWe did not see the film.\nDid you enjoy the concert?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:future_examples', '{"reply":"Aquí tienes ejemplos para hablar del futuro:\n\nEnglish: I am going to study tonight.\nEspañol: Voy a estudiar esta noche.\n\nEnglish: She will call you tomorrow.\nEspañol: Ella te llamará mañana.\n\nEnglish: We are going to travel next week.\nEspañol: Vamos a viajar la semana que viene.\n\nEnglish: I think it will be sunny.\nEspañol: Creo que hará sol.","spokenSpanish":"Aquí tienes ejemplos para hablar del futuro:","pronunciationText":"I am going to study tonight.\nShe will call you tomorrow.\nWe are going to travel next week.\nI think it will be sunny.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:present_perfect_examples', '{"reply":"Aquí tienes ejemplos del presente perfecto:\n\nEnglish: I have finished my homework.\nEspañol: He terminado los deberes.\n\nEnglish: She has never been to Scotland.\nEspañol: Ella nunca ha estado en Escocia.\n\nEnglish: Have you ever tried sushi?\nEspañol: ¿Has probado sushi alguna vez?\n\nEnglish: We have lived here for five years.\nEspañol: Vivimos aquí desde hace cinco años.","spokenSpanish":"Aquí tienes ejemplos del presente perfecto:","pronunciationText":"I have finished my homework.\nShe has never been to Scotland.\nHave you ever tried sushi?\nWe have lived here for five years.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:verb_to_be_examples', '{"reply":"Aquí tienes ejemplos del verbo to be:\n\nEnglish: I am ready.\nEspañol: Estoy listo.\n\nEnglish: She is a teacher.\nEspañol: Ella es profesora.\n\nEnglish: They are at home.\nEspañol: Están en casa.\n\nEnglish: Are you tired?\nEspañol: ¿Estás cansado?","spokenSpanish":"Aquí tienes ejemplos del verbo to be:","pronunciationText":"I am ready.\nShe is a teacher.\nThey are at home.\nAre you tired?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:articles_a_an_examples', '{"reply":"Aquí tienes ejemplos de a y an:\n\nEnglish: I have a dog.\nEspañol: Tengo un perro.\n\nEnglish: She ate an apple.\nEspañol: Ella se comió una manzana.\n\nEnglish: He is a university student.\nEspañol: Él es estudiante universitario.\n\nEnglish: It took an hour.\nEspañol: Tardó una hora.","spokenSpanish":"Aquí tienes ejemplos de a y an:","pronunciationText":"I have a dog.\nShe ate an apple.\nHe is a university student.\nIt took an hour.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:subject_pronouns_examples', '{"reply":"Aquí tienes ejemplos de pronombres personales:\n\nEnglish: I am learning English.\nEspañol: Estoy aprendiendo inglés.\n\nEnglish: He works in a bank.\nEspañol: Él trabaja en un banco.\n\nEnglish: We live in Spain.\nEspañol: Vivimos en España.\n\nEnglish: They are my friends.\nEspañol: Son mis amigos.","spokenSpanish":"Aquí tienes ejemplos de pronombres personales:","pronunciationText":"I am learning English.\nHe works in a bank.\nWe live in Spain.\nThey are my friends.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:question_words_examples', '{"reply":"Aquí tienes ejemplos de palabras interrogativas:\n\nEnglish: What is your name?\nEspañol: ¿Cómo te llamas?\n\nEnglish: Where do you live?\nEspañol: ¿Dónde vives?\n\nEnglish: When does the train leave?\nEspañol: ¿Cuándo sale el tren?\n\nEnglish: Why are you learning English?\nEspañol: ¿Por qué estás aprendiendo inglés?\n\nEnglish: How does this work?\nEspañol: ¿Cómo funciona esto?","spokenSpanish":"Aquí tienes ejemplos de palabras interrogativas:","pronunciationText":"What is your name?\nWhere do you live?\nWhen does the train leave?\nWhy are you learning English?\nHow does this work?","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:can_could_examples', '{"reply":"Aquí tienes ejemplos con can y could:\n\nEnglish: I can swim.\nEspañol: Sé nadar.\n\nEnglish: Could you help me, please?\nEspañol: ¿Podría ayudarme, por favor?\n\nEnglish: Can I open the window?\nEspañol: ¿Puedo abrir la ventana?\n\nEnglish: When I was younger, I could run faster.\nEspañol: Cuando era más joven, podía correr más rápido.","spokenSpanish":"Aquí tienes ejemplos con can y could:","pronunciationText":"I can swim.\nCould you help me, please?\nCan I open the window?\nWhen I was younger, I could run faster.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:comparatives_examples', '{"reply":"Aquí tienes ejemplos de comparativos:\n\nEnglish: This book is cheaper than that one.\nEspañol: Este libro es más barato que aquel.\n\nEnglish: My brother is taller than me.\nEspañol: Mi hermano es más alto que yo.\n\nEnglish: English is easier with practice.\nEspañol: El inglés es más fácil con práctica.\n\nEnglish: Today is colder than yesterday.\nEspañol: Hoy hace más frío que ayer.","spokenSpanish":"Aquí tienes ejemplos de comparativos:","pronunciationText":"This book is cheaper than that one.\nMy brother is taller than me.\nEnglish is easier with practice.\nToday is colder than yesterday.","feedback":null}', 'prepared');
INSERT INTO tutor_response_cache (cache_key, response_json, response_kind) VALUES ('prepared:polite_requests_examples', '{"reply":"Aquí tienes frases para hacer peticiones educadas:\n\nEnglish: Could you speak more slowly, please?\nEspañol: ¿Podría hablar más despacio, por favor?\n\nEnglish: Would you mind opening the window?\nEspañol: ¿Le importaría abrir la ventana?\n\nEnglish: Could you repeat that, please?\nEspañol: ¿Podría repetirlo, por favor?\n\nEnglish: May I ask you a question?\nEspañol: ¿Puedo hacerle una pregunta?","spokenSpanish":"Aquí tienes frases para hacer peticiones educadas:","pronunciationText":"Could you speak more slowly, please?\nWould you mind opening the window?\nCould you repeat that, please?\nMay I ask you a question?","feedback":null}', 'prepared');
