-- Cache of prepared tutor answers and reusable generic responses.
-- Prepared entries never expire; learned cache entries expire after 45 days in application code.
CREATE TABLE IF NOT EXISTS tutor_response_cache (
  cache_key TEXT PRIMARY KEY,
  response_json TEXT NOT NULL CHECK (json_valid(response_json)),
  response_kind TEXT NOT NULL CHECK (response_kind IN ('prepared', 'cached')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_tutor_response_cache_kind_created
  ON tutor_response_cache (response_kind, created_at);

